/**
 * Ровное симметричное сердце в заданной рамке.
 *
 * Обводка с рисунка не годится: сердце Рита ведёт от руки, лево и
 * право получаются разными, и на экране это читается как кривизна,
 * а не как рукотворность. Остальные детали обведены как есть —
 * там неровность к месту, а у сердца форма геометрическая.
 *
 * Кривая единичная, поэтому одна и та же форма годится и для
 * пуговицы, и для мехового сердца — меняется только рамка.
 *
 * ВЫЕМКА 0.18, А НЕ 0.27
 * Глубокая выемка съедала место сверху: круглый ободок нитки подходил
 * к ней вплотную, и сердце приходилось раздувать. С мелкой выемкой
 * сердце вышло МЕНЬШЕ (185 против 209) и с бОльшим просветом
 * (8.4 против 5.0).
 */
const UNIT = [
  [0.50, 0.18], [0.50, 0.07], [0.35, 0.00], [0.21, 0.00],
  [0.05, 0.00], [0.00, 0.17], [0.00, 0.32],
  [0.00, 0.53], [0.17, 0.72], [0.50, 1.00],
  [0.83, 0.72], [1.00, 0.53], [1.00, 0.32],
  [1.00, 0.17], [0.95, 0.00], [0.79, 0.00],
  [0.65, 0.00], [0.50, 0.07], [0.50, 0.18],
];

/**
 * `s` — доля от полного размера, СЖАТИЕ ОТ ЦЕНТРА, а не отступ рамки.
 * Отступ уменьшает ширину и высоту на одинаковое число, а не в
 * одинаковой доле: сердце 148×139 при отступе 20 сжимается по x
 * сильнее, чем по y, и у верхней выемки вложенные кривые пересекаются.
 */
export function heart(x0, y0, x1, y1, s = 1) {
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  const w = (x1 - x0) * s, h = (y1 - y0) * s;
  x0 = cx - w / 2; y0 = cy - h / 2;
  const X = (u) => (x0 + u * w).toFixed(1);
  const Y = (v) => (y0 + v * h).toFixed(1);
  const p = UNIT;
  let d = `M${X(p[0][0])},${Y(p[0][1])}`;
  for (let i = 1; i < p.length; i += 3) {
    d += `C${X(p[i][0])},${Y(p[i][1])} ${X(p[i+1][0])},${Y(p[i+1][1])} ${X(p[i+2][0])},${Y(p[i+2][1])}`;
  }
  return d + 'Z';
}

/**
 * Рамка мехового сердца — того, что появляется на голове за пуговицей.
 * Пуговица-сердце убрана, осталась только эта.
 */
export const HEART_BOX = {
  fur: [84, 96, 308, 327],
};

